<script lang="ts">
  import { page } from '$app/state';
  import { goto } from '$app/navigation';
  import { onMount } from 'svelte';
  import { Button } from '$lib/components/ui/button';
  import { Input } from '$lib/components/ui/input';
  import { Textarea } from '$lib/components/ui/textarea';
  import { Compass, Clapperboard, FolderOpen, Coins, Radio, ChartNoAxesCombined, Settings, ArrowUpRight, ArrowRight, Plus, Play, Film, LogOut, LoaderCircle, Sparkles, Check, ShieldCheck, Heart } from '@lucide/svelte';
  import { request, CloudError } from './api';
  import type { Project, Quote } from './generated';
  import './cloud.css';
  import VideoPlayer from './VideoPlayer.svelte';
  import Studio from './Studio.svelte';
  let user = $state<any>(null);
  let ready = $state(!!page.data.cloudPublic);
  let loading = $state(!page.data.cloudPublic);
  let loadFailed = $state(false);
  let busy = $state(false);
  let error = $state('');
  let notice = $state('');
  let data = $state<any>(page.data.cloudPublic || {});
  let projects = $state<Project[]>([]);
  let jobs = $state<any[]>([]);
  let email = $state(''); let password = $state(''); let name = $state(''); let handle = $state('');
  let prompt = $state(''); let duration = $state('10'); let ratio = $state('16:9'); let projectId = $state('');
  let projectName = $state(''); let projectDescription = $state('');
  let quote = $state<Quote | null>(null); let quoteKey = '';
  let channelName = $state(''); let channelDescription = $state('');
  let title = $state(''); let description = $state(''); let jobId = $state(''); let visibility = $state('private'); let audience = $state('free');
  let playback = $state('');
  let plan = $state<any>({}); let planPrice = $state(''); let planEnabled = $state(false);
  let payout = $state<any>({}); let payoutCountry = $state('');
  let reportReason = $state(''); let showReport = $state(false); let followed = $state(false);
  const creditCheckoutKeys = new Map<string,string>();
  function buyCredits(packId:string) {
    let key=creditCheckoutKeys.get(packId);
    if(!key){key=crypto.randomUUID();creditCheckoutKeys.set(packId,key);}
    void action(async()=>{const result=await request('/billing/checkout',{pack_id:packId},'POST',{'Idempotency-Key':key!});window.location.assign(result.url);});
  }
  let membershipCheckoutKey = ''; let membershipCheckoutChannel = '';
  function joinChannel(channelId:string) {
    if (!user) { void goto('/login'); return; }
    if (membershipCheckoutChannel !== channelId) {membershipCheckoutKey='';membershipCheckoutChannel=channelId;}
    membershipCheckoutKey ||= crypto.randomUUID();
    void action(async()=>{const result=await request('/memberships/checkout',{channel_id:channelId},'POST',{'Idempotency-Key':membershipCheckoutKey});window.location.assign(result.url);});
  }
  let token = $state(''); let developmentToken = $state('');
  const path = $derived(page.url.pathname);
  const recoveryPage = $derived(['/forgot-password','/reset-password','/verify-email'].includes(path));
  const authPage = $derived(path === '/login' || path === '/register' || recoveryPage);
  const publicPage = $derived(path === '/' || path.startsWith('/watch/') || path.startsWith('/channels/'));
  const nav = [ {url:'/',label:'Discover',icon:Compass}, {url:'/create',label:'Create video',icon:Clapperboard}, {url:'/projects',label:'Projects',icon:FolderOpen}, {url:'/studio',label:'Advanced studio',icon:Film}, {url:'/channel',label:'Your channel',icon:Radio}, {url:'/credits',label:'Credits',icon:Coins}, {url:'/earnings',label:'Earnings',icon:ChartNoAxesCombined}, {url:'/memberships',label:'Memberships',icon:Heart} ];
  const titles: Record<string,string> = {'/':'Discover','/create':'Create video','/projects':'Projects','/credits':'Credits & billing','/channel':'Your channel','/earnings':'Creator earnings','/studio':'Advanced studio','/settings':'Account settings','/memberships':'Your memberships'};
  const list = (value:any):any[] => Array.isArray(value) ? value : value?.items || value?.videos || value?.projects || value?.jobs || [];
  const money = (cents:number | undefined, currency = 'USD') => cents == null ? '—' : new Intl.NumberFormat('en-US',{style:'currency',currency}).format(cents/100);
  const date = (value:string) => value ? new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : '—';
  onMount(() => {
    token = page.url.searchParams.get('token') || '';
    request('/me').then(v => user = v.user || v).catch(e => {
      if (!(e instanceof CloudError && e.status === 401)) error = e.message;
    }).finally(() => ready = true);
    const poll = setInterval(() => {
      if (user && path === '/create' && jobs.some(job => ['queued','running','processing','submitted'].includes(job.status))) {
        request('/jobs').then(value => jobs = list(value)).catch(() => {});
      }
    }, 10000);
    return () => clearInterval(poll);
  });
  $effect(() => { const incoming=page.url.searchParams.get('token'); if (recoveryPage && incoming) token=incoming; });
  $effect(() => { if (ready) { const current = path; if (page.data.cloudPath === current && page.data.cloudPublic) { data = page.data.cloudPublic; loading = false; } else void load(current); } });
  async function load(current:string) {
    loading = true; loadFailed = false; error = ''; notice = ''; data = {}; playback = ''; quote = null; showReport = false; reportReason = ''; followed = false; membershipCheckoutKey = '';
    if (authPage) { loading = false; return; }
    if (!user && !publicPage) { loading = false; return; }
    try {
      if (current === '/') data = {videos:list(await request('/feed'))};
      else if (current === '/projects') data = {projects:list(await request('/projects'))};
      else if (current === '/create') { const [p,j] = await Promise.all([request('/projects'),request('/jobs')]); projects = list(p); jobs = list(j); }
      else if (current === '/credits') { const [balance,packs] = await Promise.all([request('/credits'),request('/billing/packs')]); data = {...balance,...packs}; }
      else if (current === '/channel') { const [channel,generations,membership] = await Promise.all([request('/channel'),request('/jobs'),request('/creator/membership-plan')]);data=channel; jobs=list(generations);plan=membership;planPrice=membership.configured ? String(membership.price_cents/100) : '';planEnabled=membership.enabled || false; channelName = data.channel?.name || data.name || ''; channelDescription = data.channel?.description || data.description || ''; }
      else if (current === '/earnings') { const [earnings,analytics,account] = await Promise.all([request('/creator/earnings'), request('/creator/analytics'),request('/creator/payout-account')]); data = {...earnings,analytics}; payout=account;payoutCountry=account.country || ''; }
      else if (current === '/memberships') data={memberships:list(await request('/memberships'))};
      else if (current.startsWith('/watch/')) { data = await request(`/videos/${encodeURIComponent(current.split('/')[2])}`); }
      else if (current.startsWith('/channels/')) data = await request(`/channels/${encodeURIComponent(current.split('/')[2])}`);
    } catch(e) { error = (e as Error).message; loadFailed = true; } finally { loading = false; }
  }
  async function action(fn:()=>Promise<void>) { busy = true; error = ''; notice = ''; try { await fn(); } catch(e) { error = (e as Error).message; } finally { busy = false; } }
  function authenticate() { void action(async () => { await request(path === '/register' ? '/auth/register' : '/auth/login', path === '/register' ? {email,password,name,handle} : {email,password}); user = await request('/me'); password = ''; await goto('/create'); }); }
  function getQuote() { void action(async () => { quote = await request('/generation/quotes',{prompt,duration:Number(duration),aspect_ratio:ratio,project_id:projectId || undefined}); quoteKey = crypto.randomUUID(); }); }
  function generate() { const quoteId=quote?.id; if(!quoteId)return; void action(async () => { await request('/generation/jobs',{quote_id:quoteId},'POST',{'Idempotency-Key':quoteKey}); quote = null; jobs = list(await request('/jobs')); notice = 'Generation submitted. Your progress is saved here.'; }); }
  function createProject() { void action(async () => { await request('/projects',{name:projectName,description:projectDescription}); projectName = ''; projectDescription = ''; data = {projects:list(await request('/projects'))}; notice = 'Project created.'; }); }
  function publish() { void action(async () => { const video = await request('/videos',{job_id:jobId,title,description,visibility,audience}); await request(`/videos/${video.id}/publish`,{}); notice = visibility === 'private' ? 'Private video saved and submitted for processing.' : 'Video submitted for publishing.'; data = await request('/channel'); }); }
</script>

<svelte:head><title>{titles[path] || (authPage ? 'Welcome' : data.title || data.channel?.name || data.name || 'Watch')} · VideoFlow</title>{#if publicPage}<link rel="canonical" href={page.url.origin + path}/><meta property="og:title" content={`${data.title || data.channel?.name || data.name || 'Discover'} · VideoFlow`}/><meta property="og:description" content={data.description || data.channel?.description || 'Stories made of imagination.'}/>{/if}<meta name="description" content="Create your next story with VideoFlow. Your video studio, channel, and creative community." /></svelte:head>
<div class="cloud-app">
  <aside class="cloud-sidebar">
    <a class="cloud-logo" href="/"><span class="logo-mark"><Play size={17} fill="currentColor" /></span>videoflow<span class="cloud-label">CLOUD</span></a>
    <div class="workspace-label">YOUR CREATIVE SPACE</div>
    <nav aria-label="Main navigation">{#each nav as item}<a href={item.url} aria-label={item.label} title={item.label} class:active={path === item.url} aria-current={path === item.url ? 'page' : undefined}><item.icon size={18}/><span>{item.label}</span>{#if item.url === '/create'}<Plus size={15} class="nav-plus" />{/if}</a>{/each}</nav>
    <div class="sidebar-bottom"><div class="studio-note"><Sparkles size={18}/><strong>Good stories start here.</strong><p>Turn a small idea into something worth watching.</p><a href="/create">Make a video <ArrowUpRight size={14}/></a></div><a class="settings-link" href="/settings"><Settings size={17}/>Settings</a>{#if user}<div class="user-row"><span class="avatar">{(user.name || user.email || 'U').slice(0,1).toUpperCase()}</span><span><strong>{user.name || 'Your workspace'}</strong><small>{user.email}</small></span><button aria-label="Sign out" onclick={() => action(async () => { await request('/auth/logout',{}); user = null; await goto('/'); })}><LogOut size={16}/></button></div>{:else}<Button href="/login" variant="outline" class="w-full">Sign in to your studio</Button>{/if}</div>
  </aside>
  <div class="cloud-body">
    <header class="cloud-topbar"><span>{titles[path] || (authPage ? 'Your next chapter' : 'VideoFlow community')}</span><div><span class="cloud-beta">EARLY ACCESS</span>{#if user}<a href="/credits" class="top-credit"><Coins size={15}/>Your credits<ArrowUpRight size={13}/></a>{:else}<a class="top-signin" href="/login">Sign in</a><Button href="/register" size="sm">Start creating <ArrowRight size={14}/></Button>{/if}</div></header>
    <main class="cloud-main">
      {#if error}<div class="cloud-alert" role="alert"><span>{error}</span><button onclick={() => load(path)}>Try again</button></div>{/if}
      {#if notice}<div class="cloud-notice" role="status"><Check size={17}/>{notice}</div>{/if}
      {#if !ready || loading}<div class="cloud-loading" role="status"><LoaderCircle class="animate-spin" size={25}/><span>Opening your creative space…</span></div>
      {:else if loadFailed}<div class="cloud-empty"><Film size={35}/><h1>Let's try that again.</h1><p>This page couldn't be loaded. Your saved work is still in your account.</p><Button onclick={()=>load(path)}>Reload page</Button></div>
      {:else if recoveryPage}
        <form class="auth-form" style="margin:30px auto" onsubmit={(e)=>{e.preventDefault();action(async()=>{ const endpoint=path === '/forgot-password' ? '/auth/forgot-password' : path === '/verify-email' ? '/auth/verify-email' : '/auth/reset-password'; const result=await request(endpoint,path === '/forgot-password' ? {email} : path === '/verify-email' ? {token} : {token,password});developmentToken=result.development_token || '';if(path === '/verify-email' && user)user=await request('/me');notice=path === '/forgot-password' ? 'If this email is registered, recovery instructions have been sent.' : path === '/verify-email' ? 'Email verified. You can return to your studio.' : 'Password reset. Sign in with your new password.';});}}>
          <span class="eyebrow">YOUR ACCOUNT</span><h2>{path === '/forgot-password' ? 'Reset your password.' : path === '/verify-email' ? 'Verify your email.' : 'A fresh start.'}</h2>
          {#if path === '/forgot-password'}<label for="recovery-email">Email address</label><Input id="recovery-email" type="email" bind:value={email} required autocomplete="email"/>{:else}<label for="token">Token from your email</label><Input id="token" bind:value={token} required autocomplete="one-time-code"/>{/if}
          {#if path === '/reset-password'}<label for="new-password">New password</label><Input id="new-password" type="password" bind:value={password} minlength={12} required autocomplete="new-password"/>{/if}
          {#if developmentToken}<p class="field-help">Local development token: <code>{developmentToken}</code></p><a href="/reset-password">Enter reset token</a>{/if}
          <Button type="submit" disabled={busy} class="w-full">Continue <ArrowRight size={16}/></Button><p class="auth-switch"><a href="/login">Back to sign in</a></p>
        </form>
      {:else if authPage}
        <div class="auth-layout"><div class="auth-story"><span class="eyebrow">A LITTLE IDEA. A WHOLE NEW WORLD.</span><h1>Your imagination,<br/>in motion.</h1><p>A place to create videos, build your channel, and find your audience.</p><div class="auth-rule"></div><span>CREATE · PUBLISH · CONNECT</span></div><form class="auth-form" onsubmit={(e) => {e.preventDefault();authenticate();}}><span class="eyebrow">WELCOME TO VIDEOFLOW</span><h2>{path === '/register' ? 'Make room for your ideas.' : 'Welcome back.'}</h2><p>{path === '/register' ? 'Create your account and open your personal studio.' : 'Sign in to pick up where you left off.'}</p>{#if path === '/register'}<label for="name">Your name</label><Input id="name" bind:value={name} required autocomplete="name"/><label for="handle">Channel handle</label><Input id="handle" bind:value={handle} required pattern={'[a-zA-Z0-9_]{3,30}'} placeholder="your_channel" autocomplete="username"/>{/if}<label for="email">Email address</label><Input id="email" type="email" bind:value={email} required autocomplete="email"/><label for="password">Password</label><Input id="password" type="password" bind:value={password} required minlength={path === '/register' ? 12 : 1} autocomplete={path === '/register' ? 'new-password' : 'current-password'}/>{#if path === '/register'}<small>Use at least 12 characters.</small>{/if}<Button type="submit" disabled={busy} class="w-full">{busy ? 'Please wait…' : path === '/register' ? 'Create account' : 'Sign in'}<ArrowRight size={16}/></Button><a class="field-help" href="/forgot-password">Forgot password?</a><p class="auth-switch">{path === '/register' ? 'Already have an account?' : 'New around here?'} <a href={path === '/register' ? '/login' : '/register'}>{path === '/register' ? 'Sign in' : 'Create an account'}</a></p></form></div>
      {:else if !user && !publicPage}
        <div class="cloud-empty"><ShieldCheck size={38}/><h1>Your studio is waiting.</h1><p>Sign in to create videos, manage projects, and grow your channel.</p><Button href="/login">Sign in <ArrowRight size={16}/></Button><a href="/register">Create an account</a></div>
      {:else if path === '/'}
        <section class="discover-intro"><div><span class="eyebrow">MADE OF IMAGINATION</span><h1>Stories worth<br/><span>stopping for.</span></h1><p>A new perspective. An unexpected world.<br/>Find what creators are bringing to life.</p><Button href="/create">Create your own <ArrowUpRight size={16}/></Button></div><div class="intro-type" aria-hidden="true"><span>MAKE</span><span>IT MOVE<span class="type-dot">.</span></span><div><span>YOUR NEXT STORY STARTS WITH YOU</span><Clapperboard size={32}/></div></div></section>
        <section><div class="section-heading"><div><span class="eyebrow">THE COMMUNITY CUT</span><h2>Fresh perspectives</h2></div><span class="subtle">Latest public videos</span></div>{#if data.videos?.length}<div class="video-grid">{#each data.videos as video}<a class="video-tile" href={`/watch/${video.id}`}><div class="video-image">{#if video.thumbnail_url}<img src={video.thumbnail_url} alt="" loading="lazy"/>{:else}<Film size={32}/>{/if}<span class="play-badge"><Play size={16}/></span></div><h3>{video.title}</h3><p>{video.channel_name || video.handle || 'VideoFlow creator'}</p></a>{/each}</div>{:else}<div class="feed-empty"><Film size={28}/><div><h3>The first stories are on their way.</h3><p>Public videos will appear here as creators publish. Yours could be the first.</p></div><Button variant="outline" href="/create">Open the studio <ArrowRight size={15}/></Button></div>{/if}</section>
      {:else if path === '/create'}
        <div class="page-heading"><span class="eyebrow">FROM THOUGHT TO FRAME</span><h1>What do you imagine?</h1><p>Describe your video. Review the cost. Bring it to life.</p></div><div class="creation-layout"><form class="cloud-panel create-form" onsubmit={(e)=>{e.preventDefault();getQuote();}}><label for="prompt" class="strong-label">The idea</label><Textarea id="prompt" bind:value={prompt} oninput={()=>quote=null} placeholder="A quiet coastal town at sunrise. A cyclist follows the winding road as the first light reaches the sea…" required minlength={10} rows={7}/><p class="field-help">Set the scene, describe the action, and tell us how it should feel.</p><div class="form-grid"><div><label for="duration">Duration</label><select id="duration" bind:value={duration} onchange={()=>quote=null}><option value="5">5 seconds</option><option value="10">10 seconds</option><option value="15">15 seconds</option><option value="30">30 seconds</option></select></div><div><label for="ratio">Frame</label><select id="ratio" bind:value={ratio} onchange={()=>quote=null}><option>16:9</option><option>9:16</option><option>1:1</option></select></div></div><label for="project">Project</label><select id="project" bind:value={projectId} onchange={()=>quote=null}><option value="">No project</option>{#each projects as project}<option value={project.id}>{project.name}</option>{/each}</select><div class="form-footer"><span><ShieldCheck size={15}/>Private until you publish</span><Button type="submit" disabled={busy || prompt.length < 10}>Review credit cost <ArrowRight size={15}/></Button></div>{#if quote}<div class="quote-box"><div><strong>{quote.credits} credits</strong><p>Quote expires {new Date(quote.expires_at).toLocaleTimeString()}. Credits are reserved when you confirm.</p></div><Button type="button" disabled={busy || Date.parse(quote.expires_at) < Date.now()} onclick={generate}>Confirm generation</Button></div>{/if}</form><aside class="creative-guide"><span class="eyebrow">A STRONG START</span><h2>Give your idea<br/>a little direction.</h2><ol><li><span>01</span><div><strong>Build a world</strong><p>Where are we? A place, a time of day, a feeling.</p></div></li><li><span>02</span><div><strong>Find the movement</strong><p>Describe what happens, from subject to camera.</p></div></li><li><span>03</span><div><strong>Make it yours</strong><p>Natural light, a cinematic mood, or something unexpected.</p></div></li></ol><div class="guide-foot"><Coins size={17}/><p>You see the credit cost before any generation starts.</p></div></aside></div><section class="jobs-section"><div class="section-heading"><h2>Your generations</h2><Button variant="ghost" size="sm" onclick={()=>action(async()=>{jobs=list(await request('/jobs'));})}>Refresh</Button></div>{#if jobs.length}<div class="record-list">{#each jobs as job}<div class="record"><Clapperboard size={19}/><div><strong>{job.prompt || job.name || 'Video generation'}</strong><small>{date(job.created_at)}</small></div><span class="status">{job.status}</span>{#if job.error}<small>{job.error}</small>{/if}{#if ['completed','succeeded','complete'].includes(job.status)}<button onclick={()=>action(async()=>{const output=await request(`/jobs/${job.id}/download`);window.open(output.url,'_blank','noopener,noreferrer');})}>Download <ArrowUpRight size={14}/></button>{/if}</div>{/each}</div>{:else}<p class="quiet-empty">Your generations will appear here. Progress stays saved when you leave.</p>{/if}</section>
      {:else if path === '/studio'}
        <Studio/>
      {:else if path === '/projects'}
        <div class="page-heading"><span class="eyebrow">YOUR WORK, TOGETHER</span><h1>A home for every idea.</h1><p>Keep your creative work organized in private projects.</p></div><div class="projects-layout"><section>{#if data.projects?.length}<div class="project-grid">{#each data.projects as project}<article class="cloud-panel project-card"><FolderOpen size={26}/><h2>{project.name}</h2><p>{project.description || 'A fresh space for your next video.'}</p><small>Created {date(project.created_at)}</small><Button variant="outline" href={`/studio?project=${project.id}`}>Open studio <ArrowUpRight size={14}/></Button></article>{/each}</div>{:else}<div class="cloud-empty compact"><FolderOpen size={35}/><h2>Big ideas need a little space.</h2><p>Create your first project to keep your work together.</p></div>{/if}</section><form class="cloud-panel" onsubmit={(e)=>{e.preventDefault();createProject();}}><h2>New project</h2><label for="project-name">Project name</label><Input id="project-name" bind:value={projectName} placeholder="My next great idea" required maxlength={100}/><label for="project-description">Description <span class="subtle">(optional)</span></label><Textarea id="project-description" bind:value={projectDescription} rows={4}/><Button type="submit" disabled={busy || !projectName.trim()}><Plus size={16}/>Create project</Button></form></div>
      {:else if path === '/credits'}
        <div class="page-heading"><span class="eyebrow">FUEL YOUR NEXT IDEA</span><h1>A little credit. A lot of possibility.</h1><p>Credits power your generations. Your confirmed balance is always here.</p></div>{#if data.restricted || data.debt > 0}<div class="cloud-alert" role="alert"><div><strong>{data.restricted ? 'Generation is restricted on your account.' : 'Your account has an outstanding credit balance.'}</strong>{#if data.debt > 0}<p>Outstanding debt: {data.debt.toLocaleString()} credits.</p>{/if}<p>Review your credit activity for payment reversals and adjustments.</p></div></div>{/if}<div class="balance-strip"><div><span>Available credits</span><strong>{data.available ?? '—'}<Coins size={25}/></strong></div><div><span>Reserved for generation</span><strong>{data.reserved ?? '—'}</strong></div><p>Generation credits are used in the studio and cannot be withdrawn as cash.</p></div><div class="section-heading"><h2>Top up your creativity</h2></div>{#if !data.checkout_enabled}<div class="info-banner"><Coins size={20}/><div><strong>Credit purchases are not open yet.</strong><p>Checkout will become available when pricing and payments are configured.</p></div></div>{/if}<div class="pack-grid">{#each data.packs || [] as pack}<article class="cloud-panel"><span class="eyebrow">{pack.name}</span><h2>{pack.credits.toLocaleString()} <small>credits</small></h2><p class="pack-price">{money(pack.price_cents,pack.currency)}</p><Button disabled={!data.checkout_enabled || busy} onclick={()=>buyCredits(pack.id)}>Buy credits <ArrowUpRight size={15}/></Button></article>{/each}</div><section class="jobs-section"><h2>Credit activity</h2>{#if data.transactions?.length}<div class="record-list">{#each data.transactions as transaction}<div class="record"><Coins size={18}/><div><strong>{transaction.description || transaction.kind}</strong><small>{date(transaction.created_at)}</small></div><strong>{transaction.amount ?? transaction.credits}</strong></div>{/each}</div>{:else}<p class="quiet-empty">Purchases, reservations, and refunds will appear here.</p>{/if}</section>
      {:else if path === '/channel'}
        <div class="page-heading"><span class="eyebrow">YOUR CORNER OF VIDEOFLOW</span><h1>Build something people follow.</h1><p>Shape your channel and choose what you share with the world.</p></div><div class="channel-banner"><span class="channel-avatar">{(channelName || user.name || 'V').slice(0,1).toUpperCase()}</span><div><h2>{channelName || user.name}</h2><p>@{data.channel?.handle || data.handle || user.handle}</p></div><a href={`/channels/${data.channel?.handle || data.handle || user.handle}`}>View channel <ArrowUpRight size={16}/></a></div><div class="projects-layout"><form class="cloud-panel" onsubmit={(e)=>{e.preventDefault();action(async()=>{await request('/channel',{name:channelName,description:channelDescription},'PATCH');notice='Channel updated.';});}}><h2>Channel details</h2><label for="channel-name">Channel name</label><Input id="channel-name" bind:value={channelName} required/><label for="channel-description">About your channel</label><Textarea id="channel-description" bind:value={channelDescription} rows={4}/><Button disabled={busy} type="submit">Save changes</Button></form><form class="cloud-panel" onsubmit={(e)=>{e.preventDefault();publish();}}><h2>Share a finished video</h2><label for="job">Completed generation</label><select id="job" bind:value={jobId} required><option value="">Choose a generation</option>{#each jobs.filter(j=>['completed','succeeded','complete'].includes(j.status)) as job}<option value={job.id}>{job.prompt || job.name || job.id}</option>{/each}</select><label for="video-title">Title</label><Input id="video-title" bind:value={title} required/><label for="video-description">Description</label><Textarea id="video-description" bind:value={description}/><div class="form-grid"><div><label for="visibility">Visibility</label><select id="visibility" bind:value={visibility}><option value="private">Private</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select></div><div><label for="audience">Audience</label><select id="audience" bind:value={audience}><option value="free">Everyone</option><option value="members">Members only</option></select></div></div><p class="field-help">Published videos show an AI-generated disclosure. Playback is available after processing and review.</p><Button type="submit" disabled={busy || !jobId || !title}>{visibility === 'private' ? 'Save private video' : 'Publish video'}<ArrowUpRight size={15}/></Button></form></div><section class="cloud-panel membership-editor jobs-section"><div><span class="eyebrow">A CLOSER CREATIVE CIRCLE</span><h2>Channel membership</h2><p>Offer access to members-only videos through a monthly subscription. Free follows remain separate.</p>{#if !plan.sales_enabled}<div class="info-banner"><ShieldCheck size={18}/><p>Membership sales are not enabled. You can save a draft price. Sales require an approved policy and eligible creator payment account.</p></div>{/if}</div><form onsubmit={(e)=>{e.preventDefault();action(async()=>{await request('/creator/membership-plan',{price_cents:Math.round(Number(planPrice)*100),currency:'usd',enabled:planEnabled},'PUT');plan=await request('/creator/membership-plan');notice='Membership plan saved.';});}}><label for="membership-price">Monthly price (USD)</label><Input id="membership-price" type="number" bind:value={planPrice} min="1" max="10000" step="0.01" required placeholder="Enter a monthly price"/><label class="checkbox-label"><input type="checkbox" bind:checked={planEnabled} disabled={!plan.sales_enabled}/> Enable membership sales</label><Button type="submit" disabled={busy || !planPrice}>Save membership plan</Button></form></section><section class="jobs-section"><h2>Your publications</h2>{#each data.videos || [] as video}<div class="record"><Film size={18}/><div><strong>{video.title}</strong><small>{video.visibility} · {video.status}</small></div><a href={`/watch/${video.id}`}>View <ArrowUpRight size={14}/></a></div>{:else}<p class="quiet-empty">Your published and private videos will appear here.</p>{/each}</section>
      {:else if path === '/earnings'}
        <div class="page-heading"><span class="eyebrow">CREATOR BUSINESS</span><h1>Your creativity, in numbers.</h1><p>Track your audience and confirmed creator earnings.</p></div><div class="metric-grid">{#each [{label:'Validated views',value:data.analytics?.views},{label:'Watch minutes',value:data.analytics?.watch_minutes},{label:'Followers',value:data.analytics?.followers},{label:'Published videos',value:data.analytics?.videos}] as metric}<div><span>{metric.label}</span><strong>{metric.value ?? '—'}</strong></div>{/each}</div><div class="section-heading"><h2>Earnings</h2><span class="subtle">{data.currency || 'USD'}</span></div><div class="balance-strip"><div><span>Available</span><strong>{money(data.available_cents,data.currency)}</strong></div><div><span>Pending</span><strong>{money(data.pending_cents,data.currency)}</strong></div><div><span>Paid to date</span><strong>{money(data.paid_cents,data.currency)}</strong></div></div>{#if !data.rewards_enabled}<div class="info-banner"><ShieldCheck size={21}/><div><strong>Creator rewards are not enabled.</strong><p>Eligibility, rewards policy, and payouts must be approved before earnings can be activated. There is no guaranteed payment per view.</p></div></div>{/if}<section class="cloud-panel payout-panel"><div><span class="eyebrow">GET READY TO EARN</span><h2>Payout account</h2><p>{payout.configured ? `Account connected${payout.country ? ' in ' + payout.country : ''}.` : 'Connect an eligible account to complete identity and payment verification.'}</p><p class="field-help">{payout.payouts_enabled ? 'Payment provider account verified.' : 'Payment provider verification is incomplete.'} {payout.cash_payouts_enabled ? 'Cash payouts are enabled.' : 'Cash payouts are not enabled. Connecting an account does not activate payouts.'}</p></div><form onsubmit={(e)=>{e.preventDefault();action(async()=>{const result=await request('/creator/payout-account',{country:payoutCountry.toUpperCase()});window.location.assign(result.url);});}}><label for="payout-country">Country code</label><Input id="payout-country" bind:value={payoutCountry} placeholder="e.g. US" pattern="[A-Za-z][A-Za-z]" maxlength={2} required disabled={payout.configured}/><p class="field-help">Use your legal residence's two-letter country code. Availability is checked before onboarding.</p><Button type="submit" disabled={busy || !payout.onboarding_enabled || !user.verified}>{payout.configured ? 'Continue verification' : 'Set up payout account'}<ArrowUpRight size={15}/></Button>{#if !payout.onboarding_enabled}<p class="field-help">Payout onboarding is not available yet.</p>{:else if !user.verified}<p class="field-help">Verify your email in account settings to continue.</p>{/if}</form></section><h2 class="jobs-section">Earnings activity</h2>{#each data.entries || [] as entry}<div class="record"><div><strong>{entry.description || entry.kind}</strong><small>{date(entry.created_at)}</small></div><span>{money(entry.amount_cents,data.currency)}</span></div>{:else}<p class="quiet-empty">Confirmed earnings and adjustments will appear here.</p>{/each}
      {:else if path === '/memberships'}
        <div class="page-heading"><span class="eyebrow">SUPPORT THE STORIES YOU LOVE</span><h1>Your creative circle.</h1><p>Your paid channel memberships and current access, all in one place.</p></div><div class="info-banner"><Heart size={19}/><div><strong>Memberships support individual creators.</strong><p>They provide channel-specific access and are separate from studio generation credits. A free follow does not grant member-only access.</p></div></div>{#if data.memberships?.length}<div class="record-list">{#each data.memberships as membership}<div class="record"><Heart size={20}/><div><strong>{membership.channel_name}</strong><small>@{membership.handle} · Paid through {date(membership.paid_through)}</small></div><span class="status">{membership.active ? 'Access active' : membership.status}</span><a href={`/channels/${membership.handle}`}>Visit channel <ArrowUpRight size={14}/></a></div>{/each}</div>{:else}<div class="cloud-empty compact"><Heart size={36}/><h2>Find a story you want to be part of.</h2><p>Your channel memberships will appear here once a purchase is confirmed.</p><Button href="/">Discover creators <ArrowRight size={15}/></Button></div>{/if}
      {:else if path === '/settings'}
        <div class="page-heading"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>Your account.</h1><p>Your identity across your studio and channel.</p></div><section class="cloud-panel account-panel"><h2>Personal details</h2><dl><div><dt>Name</dt><dd>{user.name}</dd></div><div><dt>Email address</dt><dd>{user.email}</dd></div><div><dt>Channel handle</dt><dd>@{user.handle}</dd></div><div><dt>Email verification</dt><dd>{user.verified ? 'Verified' : 'Verification pending'}</dd></div></dl>{#if !user.verified}<p class="field-help">Check your inbox for a verification email before using features that require a verified account.</p><Button variant="outline" disabled={busy} onclick={()=>action(async()=>{const result=await request('/auth/resend-verification',{email:user.email});developmentToken=result.development_token || '';notice='Verification instructions sent. Check your inbox.';})}>Resend verification email</Button><a href="/verify-email" class="field-help">Enter verification token</a>{#if developmentToken}<p class="field-help">Local development token: <code>{developmentToken}</code></p>{/if}{/if}<Button variant="outline" href="/channel">Edit channel profile <ArrowUpRight size={15}/></Button></section>
        <section class="cloud-panel account-panel jobs-section"><h2>Privacy & account control</h2><p class="field-help">Clear the viewing history used for your account. Your memberships, purchases, and saved projects remain available.</p><Button variant="outline" disabled={busy} onclick={()=>{if(window.confirm('Clear your viewing history? This cannot be undone.'))action(async()=>{await request('/viewer/history',{},'DELETE');notice='Your viewing history has been cleared.';});}}>Clear viewing history</Button><div class="account-deletion"><h3>Request account deletion</h3><p class="field-help">This submits a deletion request and immediately signs you out of all sessions. Financial and legal records follow the platform retention policy; they are not deleted immediately.</p><Button variant="destructive" disabled={busy} onclick={()=>{if(window.confirm('Request account deletion and sign out of all sessions? Financial and legal records are retained under the platform policy.'))action(async()=>{await request('/account/deletion',{});user=null;await goto('/login');notice='Account deletion requested. You have been signed out of all sessions. Financial and legal records follow the platform retention policy.';});}}>Request account deletion</Button></div></section>
      {:else if path.startsWith('/watch/')}
        <div class="watch-layout"><div class="player">{#if playback}<VideoPlayer videoId={data.id || path.split('/')[2]} onerror={(message)=>{error=message;playback='';}}/>{:else}<Film size={48}/><p>{data.status === 'ready' || data.status === 'published' ? 'Ready when you are.' : `Video ${data.status || 'is being prepared'}`}</p><Button disabled={busy} onclick={()=>action(async()=>{playback='play';})}><Play size={17}/>Play video</Button>{/if}</div><div class="watch-title"><h1>{data.title || 'Video'}</h1><span class="status">AI-generated</span></div><p>{data.description}</p>{#if data.channel_handle || data.handle}<a href={`/channels/${data.channel_handle || data.handle}`} class="creator-link">@{data.channel_handle || data.handle}<ArrowUpRight size={15}/></a>{/if}<div class="report-section">{#if user}<button class="report-toggle" onclick={()=>showReport=!showReport}>{showReport ? 'Cancel report' : 'Report this video'}</button>{#if showReport}<form onsubmit={(e)=>{e.preventDefault();action(async()=>{await request(`/videos/${data.id || path.split('/')[2]}/report`,{reason:reportReason});notice='Report submitted for review.';showReport=false;reportReason='';});}}><label for="report-reason">Tell us what should be reviewed</label><Textarea id="report-reason" bind:value={reportReason} minlength={5} maxlength={2000} required rows={3}/><p class="field-help">Include details about a content policy or copyright concern. Reports are reviewed by the platform.</p><Button type="submit" variant="outline" disabled={busy || reportReason.trim().length < 5}>Submit report</Button></form>{/if}{:else}<a class="report-toggle" href="/login">Sign in to report a concern</a>{/if}</div></div>
      {:else if path.startsWith('/channels/')}
        <div class="channel-banner"><span class="channel-avatar">{(data.channel?.name || data.name || 'V').slice(0,1)}</span><div><h1>{data.channel?.name || data.name || path.split('/')[2]}</h1><p>@{data.channel?.handle || data.handle || path.split('/')[2]}</p></div></div><p class="channel-about">{data.channel?.description || data.description}</p><div class="community-actions"><span class="subtle">{data.followers ?? data.channel?.followers ?? '—'} followers</span>{#if user?.channel_id !== (data.id || data.channel?.id)}<Button variant="outline" disabled={busy || followed} onclick={()=>{if(!user){void goto('/login');return;}action(async()=>{await request(`/channels/${data.id || data.channel?.id}/follow`,{});followed=true;notice='You are now following this channel.';});}}><Heart size={16}/>{followed ? 'Following' : 'Follow for free'}</Button>{#if data.membership_plan?.enabled && data.membership_plan?.sales_enabled}<Button disabled={busy} onclick={()=>joinChannel(data.id || data.channel?.id)}>Join · {money(data.membership_plan.price_cents,data.membership_plan.currency)}/month<ArrowUpRight size={15}/></Button>{/if}{/if}</div><h2>Videos</h2><div class="video-grid">{#each data.videos || [] as video}<a class="video-tile" href={`/watch/${video.id}`}><div class="video-image">{#if video.thumbnail_url}<img src={video.thumbnail_url} alt=""/>{:else}<Film size={30}/>{/if}</div><h3>{video.title}</h3></a>{:else}<p class="quiet-empty">This creator hasn't published any public videos yet.</p>{/each}</div>
      {:else}<div class="cloud-empty"><Compass size={35}/><h1>A little off the beaten path.</h1><p>This page isn't part of your cloud studio.</p><Button href="/">Back to discover</Button></div>{/if}
      <footer class="cloud-footer"><span>VideoFlow — a space for your imagination.</span><span>Create something worth sharing.</span></footer>
    </main>
  </div>
</div>
